<div class="page-head"><div><p class="section-kicker">Inquiry #<?= (int)$inquiry['id'] ?></p><h1><?= e($inquiry['subject']) ?></h1><p><?= e($inquiry['customer_name']) ?> · <?= e($inquiry['customer_email']?:$inquiry['customer_phone']) ?></p></div><div class="button-row"><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/inquiries">Back to inquiries</a><?php if($quotesEnabled): ?><a class="btn" href="<?= e_attr($basePath) ?>/admin/quotes/edit&inquiry_id=<?= (int)$inquiry['id'] ?>">Create quote</a><?php endif; ?></div></div>
<?php if($error): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="workspace-grid"><section class="card"><div class="card-heading"><div><h2>Customer request</h2><p class="card-subtitle">Received <?= e(date('M j, Y g:i a',strtotime($inquiry['created_at']))) ?></p></div></div><div class="prose-panel"><?= nl2br(e($inquiry['message'])) ?></div><dl class="status-list"><div><dt>Email</dt><dd><?= e($inquiry['customer_email']?:'—') ?></dd></div><div><dt>Phone</dt><dd><?= e($inquiry['customer_phone']?:'—') ?></dd></div><div><dt>Source submission</dt><dd><?= $inquiry['source_submission_id']?(int)$inquiry['source_submission_id']:'Direct inquiry' ?></dd></div></dl></section>
<section class="card"><div class="card-heading"><div><h2>Pipeline</h2><p class="card-subtitle">Assign ownership and keep the next action visible.</p></div></div><form method="post" action="<?= e_attr($basePath) ?>/admin/inquiries/view&id=<?= (int)$inquiry['id'] ?>"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)$inquiry['id'] ?>"><label>Status<select name="status"><?php foreach($statuses as $status): ?><option value="<?= e_attr($status) ?>" <?= $inquiry['status']===$status?'selected':'' ?>><?= e(ucwords($status)) ?></option><?php endforeach; ?></select></label><label>Priority<select name="priority"><?php foreach($priorities as $priority): ?><option value="<?= e_attr($priority) ?>" <?= $inquiry['priority']===$priority?'selected':'' ?>><?= e(ucwords($priority)) ?></option><?php endforeach; ?></select></label><label>Assigned to<select name="assigned_admin_id"><option value="">Unassigned</option><?php foreach($admins as $admin): ?><option value="<?= (int)$admin['id'] ?>" <?= (int)$inquiry['assigned_admin_id']===(int)$admin['id']?'selected':'' ?>><?= e($admin['name']) ?></option><?php endforeach; ?></select></label><button class="btn" name="action" value="update">Update inquiry</button></form></section></div>
<section class="card"><div class="card-heading"><div><h2>Internal notes</h2><p class="card-subtitle">Private history shared by administrators.</p></div></div><form method="post" action="<?= e_attr($basePath) ?>/admin/inquiries/view&id=<?= (int)$inquiry['id'] ?>"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)$inquiry['id'] ?>"><label>Add note<textarea name="note" rows="3" required></textarea></label><button class="btn secondary" name="action" value="note">Add note</button></form><?php if(!$inquiry['notes']): ?><div class="empty-state"><span>No internal notes yet.</span></div><?php else: ?><div class="timeline-list"><?php foreach($inquiry['notes'] as $note): ?><article><strong><?= e($note['admin_name']?:'Administrator') ?></strong><time><?= e(date('M j, Y g:i a',strtotime($note['created_at']))) ?></time><p><?= nl2br(e($note['body'])) ?></p></article><?php endforeach; ?></div><?php endif; ?></section>
